// A SIB in ICL (close to the example in IEEE 1687, simplified)
Module SIB {
  ScanInPort    si;
  ScanOutPort   so     { Source SR; }
  ScanOutPort   toSI   { Source si; }
  ScanInPort    fromSO;
  SelectPort    sel;
  ToSelectPort  toSel  { Source SR; }
  ShiftEnPort   se;  CaptureEnPort ce;  UpdateEnPort ue;
  ResetPort     rst; TCKPort       tck;
  ScanRegister  SR { ScanInSource sibMux; CaptureSource 1'b0; ResetValue 1'b0; }
  ScanMux sibMux SelectedBy SR {
    1'b0 : si;
    1'b1 : fromSO;
  }
}

// An instrument TDR (illustration)
Module mbist_tdr {
  ScanInPort  si;   ScanOutPort so { Source R[0]; }
  SelectPort  sel;  ShiftEnPort se;  CaptureEnPort ce;  UpdateEnPort ue;
  ResetPort   rst;  TCKPort tck;
  DataOutPort config[7:0] { Source R[15:8]; }
  DataInPort  status[7:0];
  ScanRegister R[15:0] { ScanInSource si; CaptureSource status[7:0], 8'b0; ResetValue 16'b0; }
  Alias start = R[15];
  Alias done  = R[7];
  Alias pass  = R[6];
}
